/**
 * Typed TypeScript facade for the wasm-bindgen package generated by:
 *
 *   wasm-pack build --target web --features wasm
 *
 * The generated package lives in `pkg/` by default, so this file assumes it is
 * placed in a sibling `bindings/` directory. Adjust the import path if your
 * frontend keeps the generated package elsewhere.
 */

import init, {
  parse_hit,
  serialize_hit,
  validate_hit,
} from "../pkg/ruhit.js";

export interface Position {
  /** 1-based line. */
  line: number;
  /** 1-based column, measured in Unicode scalar values. */
  column: number;
  /** 0-based byte offset. */
  offset: number;
}

export interface Span {
  start: Position;
  /** Exclusive end position. */
  end: Position;
}

export type Severity = "error" | "warning" | "info";

export interface Diagnostic {
  severity: Severity;
  code: string;
  message: string;
  span?: Span;
  line: number;
  column: number;
}

export interface Comment {
  text: string;
  inline: boolean;
  span?: Span;
}

export interface Parameter {
  key: string;
  value: Value;
  span?: Span;
  keySpan?: Span;
  valueSpan?: Span;
}

export interface Block {
  name: string;
  path?: string | null;
  rawHeader?: string;
  blockType?: string | null;
  items: Item[];
  span?: Span;
  headerSpan?: Span;
  closing?: string | null;
  closeSpan?: Span | null;
}

/** Discriminated union of the three ordered document items. */
export type Item =
  | ({ kind: "parameter" } & Parameter)
  | ({ kind: "block" } & Block)
  | ({ kind: "comment" } & Comment);

/** Array elements use external tagging so a nested value's `kind` stays flat. */
export type ArrayElement =
  | { value: Value }
  | { comment: Comment };

/** A value. Parsed values always include a span; constructed ASTs may omit it. */
export type Value =
  | {
      kind: "string";
      value: string;
      raw?: string;
      quote?: string | null;
      span?: Span;
    }
  | {
      kind: "number";
      raw?: string;
      value?: number;
      integer?: boolean;
      span?: Span;
    }
  | {
      kind: "boolean";
      value: boolean;
      span?: Span;
    }
  | {
      kind: "array";
      elements: ArrayElement[];
      multiline?: boolean;
      trailingComma?: boolean;
      span?: Span;
    }
  | {
      kind: "missing";
      span?: Span;
    };

export interface Document {
  items: Item[];
  span?: Span;
  diagnostics?: Diagnostic[];
}

export interface ParsedDocument extends Document {
  span: Span;
  diagnostics: Diagnostic[];
}

export interface Ruhit {
  /** Parse HIT text. Recoverable errors are returned in `diagnostics`. */
  parseHit(content: string): ParsedDocument;
  /** Serialize an AST back to `.i` text. */
  serializeHit(ast: Document): string;
  /** Return syntax and lint diagnostics for HIT text. */
  validateHit(content: string): Diagnostic[];
}

/** Load the WASM module and return typed wrappers around its exports. */
export async function loadRuhit(): Promise<Ruhit> {
  await init();
  return {
    parseHit: (content: string) => parse_hit(content) as ParsedDocument,
    serializeHit: (ast: Document) => serialize_hit(ast),
    validateHit: (content: string) => validate_hit(content) as Diagnostic[],
  };
}

export function hasErrors(document: Document): boolean {
  return (document.diagnostics ?? []).some(
    (diagnostic) => diagnostic.severity === "error",
  );
}
